      "card_ids": ["C26"],
      "claim": "Molecule 1 had an absolute oral bioavailability of 0.52 (0.47–0.61) in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Molecule 8 had an absolute oral bioavailability of 69% in healthy volunteers after oral versus IV dosing, supporting high bioavailability.",
      "evidence_role": "supportive"
