      "card_ids": ["C19"],
      "claim": "Molecule 3 had an absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold and contradictory to a high prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transferability molecules with direct absolute oral bioavailability measurements in healthy subjects support F >= 20%, with values from about 30% to 69%; one molecule consistently shows F < 20%, but the overall weight of direct absolute measurements supports high bioavailability.",
  "evidence_gaps": [
    "Molecule 7 groups records for GSK1322322 and brigatinib; the brigatinib record was discounted due to provenance conflict.",
    "Molecule 2's mean bioavailability is above threshold but its reported range includes subthreshold values.",
    "Molecule 9 includes a subthreshold mean (19.6%) alongside higher absolute values, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

